import ThoughtId from './ThoughtId'
import Timestamp from './Timestamp'

/** Decoded document content and optional editor fields. Child order belongs to the document view. */
interface Thought {
  archived?: Timestamp
  created: Timestamp
  /** Thought is being dynamically generated by AI. */
  generating?: boolean
  /** Temporary UI text shown during generation; never part of the document payload or lexeme membership. */
  displayValue?: string
  id: ThoughtId
  lastUpdated: Timestamp
  parentId: ThoughtId
  /** Used to track if a space is required when merging two siblings/thoughts. */
  splitSource?: ThoughtId
  /** Writer identifier derived from the access token, not an authenticated public key. See: clientId (thoughtspaceSession). */
  updatedBy: string
  value: string
}

export default Thought
